const API = 'http://localhost:3001';

export const api = {
  // کاربران
  getUsers: () => fetch(`${API}/users`).then(r => r.json()),
  
  addUser: (user) => fetch(`${API}/users`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(user)
  }).then(r => r.json()),

  deleteUser: (id) => fetch(`${API}/users/${id}`, { method: 'DELETE' }),

  // اخبار
  getNews: () => fetch(`${API}/news?_sort=date&_order=desc`).then(r => r.json()),
  
  addNews: (news) => fetch(`${API}/news`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(news)
  }).then(r => r.json()),

  deleteNews: (id) => fetch(`${API}/news/${id}`, { method: 'DELETE' }),
};
